package com.edgecloud.device.service;import static org.assertj.core.api.Assertions.*;import com.edgecloud.device.entity.HeartbeatStatus;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class HeartbeatPolicyServiceImplTest {private final HeartbeatPolicyServiceImpl policy=new HeartbeatPolicyServiceImpl();private final LocalDateTime now=LocalDateTime.of(2026,8,16,12,0);
 @Test void definesAllBoundariesAndDerivedValues(){assertThat(policy.calculate(null,null,30,90,now).status()).isEqualTo(HeartbeatStatus.UNKNOWN);assertThat(policy.calculate(now.minusSeconds(30),now.minusMinutes(5),30,90,now).status()).isEqualTo(HeartbeatStatus.ONLINE);assertThat(policy.calculate(now.minusSeconds(31),now.minusMinutes(5),30,90,now).status()).isEqualTo(HeartbeatStatus.HEALTHY);assertThat(policy.calculate(now.minusSeconds(60),now.minusMinutes(5),30,90,now).status()).isEqualTo(HeartbeatStatus.HEALTHY);var delayed=policy.calculate(now.minusSeconds(61),now.minusMinutes(5),30,90,now);assertThat(delayed.status()).isEqualTo(HeartbeatStatus.DELAYED);assertThat(delayed.consecutiveMissedHeartbeats()).isEqualTo(2);assertThat(delayed.nextExpectedHeartbeat()).isEqualTo(now.minusSeconds(31));assertThat(delayed.connectionDuration()).isEqualTo(Duration.ofMinutes(5));assertThat(policy.calculate(now.minusSeconds(90),null,30,90,now).status()).isEqualTo(HeartbeatStatus.DELAYED);assertThat(policy.calculate(now.minusSeconds(91),null,30,90,now).status()).isEqualTo(HeartbeatStatus.OFFLINE);}
 @Test void rejectsInvalidPolicy(){assertThatThrownBy(()->policy.calculate(now,null,30,30,now)).isInstanceOf(IllegalArgumentException.class);}
 @Test void controlledLocalCalculationPerformance(){List<LocalDateTime> values=new ArrayList<>();for(int i=0;i<10_000;i++)values.add(now.minusSeconds(i%120));for(int i=0;i<1000;i++)policy.calculate(values.get(i),now.minusHours(1),30,90,now);long start=System.nanoTime();for(LocalDateTime value:values)assertThat(policy.calculate(value,now.minusHours(1),30,90,now).status()).isNotNull();long millis=(System.nanoTime()-start)/1_000_000;System.out.println("SCRUM-719 controlled 10000-policy-calculations-ms="+millis);assertThat(millis).isLessThan(1000);}
}
